/// Returns the absolute value of n.
pub fn abs(n: i64) -> i64 {
    // BUG: inverted branches — returns n when negative, -n when positive
    if n < 0 { n } else { -n }
}

/// Returns true if n is strictly positive.
pub fn is_positive(n: i64) -> bool {
    // BUG: uses >= instead of > — returns true for zero
    n >= 0
}

/// Returns true if n is strictly negative.
pub fn is_negative(n: i64) -> bool {
    // BUG: uses <= instead of < — returns true for zero
    n <= 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_abs_negative() {
        assert_eq!(abs(-5), 5);
    }

    #[test]
    fn test_abs_positive() {
        assert_eq!(abs(3), 3);
    }

    #[test]
    fn test_abs_zero() {
        assert_eq!(abs(0), 0);
    }

    #[test]
    fn test_is_positive() {
        assert!(is_positive(1));
        assert!(!is_positive(0));
    }

    #[test]
    fn test_is_negative() {
        assert!(is_negative(-1));
        assert!(!is_negative(0));
    }
}

